import React, { Component } from 'react'
import Form from 'react-bootstrap/Form'
import Button from 'react-bootstrap/Button'
import Spinner from 'react-bootstrap/Spinner'
import ReactTooltip from "react-tooltip";

class LoginForm extends Component {
    
  
    handleChange = changeEvent => {
          
        ReactTooltip.hide();
        this.props.handleLoginChange(changeEvent)
        
    }
    
    handleSubmit = () => {

        this.props.handleLoginSubmit()

    }
    
    render() {
        
        const showLoginForm = this.props.showLoginForm ? {display: 'block'} : {display: 'none'}
                
        const showLoginSubmitButton = this.props.showLoginSubmitButton ? {display: 'block'} : {display: 'none'};
        const showLoginSubmitLoadingButton = this.props.showLoginSubmitLoadingButton ? {display: 'block'} : {display: 'none'};
        
        const username = this.props.username;
        const password = this.props.password;
        
        const enableLoginSubmitButton = this.props.enableLoginSubmitButton;
        
        return (
          <Form inline onSubmit={this.handleSubmit} style={showLoginForm}>
            <Form.Group>
                <Form.Label>Username</Form.Label>
                <Form.Control
                    data-tip="Must include http or https"
                    type="text"
                    name="username"
                    value={username}
                    onChange={this.handleChange} />
                    <ReactTooltip delayShow={250}/>
                    
            <Form.Label>Password</Form.Label>
                <Form.Control
                    type="password"
                    name="password"
                    value={password}
                    onChange={this.handleChange} />
                    <ReactTooltip delayShow={250}/>

              <Button variant="primary" disabled style={showLoginSubmitLoadingButton}>
                <Spinner
                  as="span"
                  animation="grow"
                  size="sm"
                  role="status"
                  aria-hidden="true"
                />
                Loading...
              </Button>
              
                          
             </Form.Group>
          </Form>
          
          
        );
    }

}

export default LoginForm;
